package com.taxplatform.startup;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Bookkeeping invariants and access/scope checks; never independent statutory tax approval. */
public final class TaxWorkbenchTests {
    private static int passed,generated;
    private TaxWorkbenchTests(){ }
    static Map<String,Object> body(Object... pairs){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)m.put((String)pairs[i],pairs[i+1]);return m;}
    static void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    static void check(String name,Runnable test){test.run();passed++;System.out.println("PASS "+name);}
    static void fail(String code,Runnable test){try{test.run();throw new AssertionError("accepted: "+code);}catch(Workspace.Problem e){eq(e.code,code);}}
    static String csv(String... rows){return TaxWorkbench.CAPITAL_HEADER+"\n"+String.join("\n",rows);}
    static String buy(){return "B1,ACC_A,ASSET_A,BUY,2024-04-01,1,3,1.00,0.01";}
    static Map<String,Object> sheet(String csv){return body("records",TaxWorkbench.parseCapital(csv),"coverage_checked",true,"same_entity_confirmed",true,"complex_events","NO","reviewed",true,"version","import1");}
    static Map<String,Object> capital(String csv){return TaxWorkbench.capital(sheet(csv));}
    static Map<String,Object> line(Map<String,Object> result,int index){return Json.map(Json.list(result.get("matches")).get(index));}
    static String tdsCsv(String... rows){return TaxWorkbench.TDS_HEADER+"\n"+String.join("\n",rows);}
    static String tdsRow(){return "C1,EMP_A,192,FY2025-26,SALARY_TOTAL,800000.00,40000.00";}
    static Map<String,Object> tdsSheet(String a,String b){return body("certificate",TaxWorkbench.parseTds(a),"statement",TaxWorkbench.parseTds(b),"same_entity_confirmed",true,"certificate_complete",true,"statement_complete",true,"version","tds1","decisions",new LinkedHashMap<>());}
    static Map<String,Object> command(Workspace w,String actor,String id,String op){return body("operation",op,"request_id",Workspace.id(),"expected_revision",w.readCase(actor,id).get("revision"),"workbench_version",w.workbench(actor,id).get("version"));}
    static Map<String,Object> capitalCommand(Workspace w,String actor,String id){Map<String,Object> b=command(w,actor,id,"CAPITAL_IMPORT");b.putAll(body("csv",csv(buy(),"S1,ACC_A,ASSET_A,SELL,2025-07-01,1,3,3.00,0.00"),"synthetic_confirmed",true,"same_entity_confirmed",true,"coverage_checked",true,"complex_events","NO"));return b;}
    static Map<String,Object> noticeCommand(Workspace w,String actor,String id){Map<String,Object> b=command(w,actor,id,"NOTICE_SAVE"),tasks=new LinkedHashMap<>();TaxWorkbench.NOTICE_TASKS.forEach(k->tasks.put(k,"TODO"));b.putAll(body("notice_id","","notice_alias","NOTICE_A","category","INCOME_TAX","section_label","USER_LABEL","received_on","2026-11-01","stated_due_on","2026-11-03","status","OPEN","checklist",tasks,"draft","","receipt_alias","","reported_on","","source_checked",false,"synthetic_confirmed",true));return b;}
    public static void main(String[] args)throws Exception{
        String three=csv(buy(),"S1,ACC_A,ASSET_A,SELL,2025-04-01,1,1,1.00,0.00","S2,ACC_A,ASSET_A,SELL,2025-04-02,1,1,1.00,0.00","S3,ACC_A,ASSET_A,SELL,2025-04-03,1,1,1.00,0.00");
        check("partial FIFO conserves paise and fee residual",()->{var r=capital(three);eq(line(r,0).get("acquisition_gross"),"0.33");eq(line(r,1).get("acquisition_gross"),"0.33");eq(line(r,2).get("acquisition_gross"),"0.34");eq(line(r,2).get("buy_fees"),"0.01");eq(r.get("gross_book_difference_total"),"2.00");eq(r.get("fees_deducted_from_difference"),false);eq(line(r,0).get("taxable_gain"),null);});
        check("FIFO ordering crosses lots only within same account and asset",()->{var r=capital(csv("B2,ACC_A,ASSET_A,BUY,2025-01-01,1,2,20,0",buy(),"S1,ACC_A,ASSET_A,SELL,2025-07-01,1,4,40,0"));eq(line(r,0).get("buy_record_id"),"B1");eq(line(r,1).get("buy_record_id"),"B2");eq(line(r,1).get("quantity"),"1");eq(r.get("gross_book_difference_total"),"29.00");});
        check("account and asset isolation leave missing lots unresolved",()->{for(String sale:List.of("S1,ACC_B,ASSET_A,SELL,2025-04-01,1,1,1,0","S1,ACC_A,ASSET_B,SELL,2025-04-01,1,1,1,0")){var r=capital(csv(buy(),sale));eq(Json.list(r.get("matches")).size(),0);eq(Json.list(r.get("unmatched_sales")).size(),1);eq(r.get("gross_book_difference_total"),null);}});
        check("later purchase cannot cover an earlier sale",()->{var r=capital(csv("B1,ACC_A,ASSET_A,BUY,2025-05-01,1,1,1,0","S1,ACC_A,ASSET_A,SELL,2025-04-01,1,1,1,0"));eq(Json.list(r.get("matches")).size(),0);eq(Json.list(r.get("unmatched_sales")).size(),1);});
        check("same-date sequence determines entered order",()->{var r=capital(csv("S1,ACC_A,ASSET_A,SELL,2025-04-01,1,1,1,0","B1,ACC_A,ASSET_A,BUY,2025-04-01,2,1,1,0"));eq(Json.list(r.get("matches")).size(),0);});
        check("same ordering key and duplicate IDs reject atomically",()->{fail("CAPITAL_AMBIGUOUS_ORDER",()->capital(csv(buy(),buy().replace("B1,","B2,"))));fail("WORKBENCH_DUPLICATE_RECORD_ID",()->capital(csv(buy(),buy())));});
        check("missing cost proceeds and fees stay unknown",()->{for(String field:List.of("1.00","0.01")){var r=capital(three.replace(field,"UNKNOWN"));eq(r.get("gross_book_difference_total"),null);eq(Json.list(r.get("issues")).contains("UNKNOWN_MATCHED_AMOUNT"),true);}});
        check("review and coverage cannot infer complete working",()->{for(String key:List.of("reviewed","coverage_checked","same_entity_confirmed")){var s=sheet(three);s.put(key,false);eq(TaxWorkbench.capital(s).get("gross_book_difference_total"),null);}for(String value:List.of("YES","UNKNOWN")){var s=sheet(three);s.put("complex_events",value);eq(TaxWorkbench.capital(s).get("gross_book_difference_total"),null);}});
        check("over-sale exposes unallocated proceeds and no aggregate",()->{var r=capital(csv(buy(),"S1,ACC_A,ASSET_A,SELL,2025-04-01,1,4,40,4"));var u=Json.map(Json.list(r.get("unmatched_sales")).get(0));eq(u.get("quantity"),"1");eq(u.get("unallocated_disposal_gross"),"10.00");eq(u.get("unallocated_fees"),"1.00");eq(r.get("gross_book_difference_total"),null);});
        check("strict decimal date period and event boundaries",()->{for(String v:List.of("","1e2","1.001","-1","01","NaN"))fail("WORKBENCH_EXPLICIT_AMOUNT_REQUIRED",()->TaxWorkbench.parseCapital(csv(buy().replace(",1.00,",","+v+","))));for(String v:List.of("0","0.000000","1.0000001")){try{TaxWorkbench.parseCapital(csv(buy().replace(",3,",","+v+",")));throw new AssertionError("quantity");}catch(Workspace.Problem expected){eq(expected.status,400);}}fail("WORKBENCH_DATE_REQUIRED",()->TaxWorkbench.parseCapital(csv(buy().replace("2024-04-01","2025-02-29"))));fail("CAPITAL_PERIOD_UNSUPPORTED",()->TaxWorkbench.parseCapital(csv(buy().replace("2024-04-01","2026-04-01"))));fail("CAPITAL_BUY_SELL_ONLY",()->TaxWorkbench.parseCapital(csv(buy().replace(",BUY,",",BONUS,"))));});
        check("normalized CSV rejects quoting native headers and identity-shaped aliases",()->{for(String value:List.of("%PDF","record_id\n",csv(buy())+"\n\n")){try{TaxWorkbench.parseCapital(value);throw new AssertionError("CSV");}catch(Workspace.Problem e){eq(e.status,400);}}fail("WORKBENCH_SYNTHETIC_ALIAS_REQUIRED",()->TaxWorkbench.parseCapital(csv(buy().replace("ACC_A","ABCDE1234F"))));});
        check("quantity micro-units and large integer allocation remain exact",()->{var r=capital(csv("B1,ACC_A,ASSET_A,BUY,2024-01-01,1,999999999.999999,999999999.99,0","S1,ACC_A,ASSET_A,SELL,2025-04-01,1,999999999.999999,999999999.99,0"));eq(line(r,0).get("gross_book_difference"),"0.00");eq(Json.list(r.get("remaining_lots")).size(),0);});
        check("generated partial allocations conserve all entered cost and proceeds",()->{for(int n=2;n<=60;n++){List<String> rows=new ArrayList<>();rows.add("B1,ACC_A,ASSET_A,BUY,2024-01-01,1,"+n+",1.01,0.07");for(int i=0;i<n;i++)rows.add("S"+i+",ACC_A,ASSET_A,SELL,2025-04-01,"+(i+1)+",1,0.02,0.01");var r=capital(csv(rows.toArray(String[]::new)));long cost=0,fee=0,proceeds=0;for(Object raw:Json.list(r.get("matches"))){var line=Json.map(raw);cost+=new java.math.BigDecimal((String)line.get("acquisition_gross")).movePointRight(2).longValueExact();fee+=new java.math.BigDecimal((String)line.get("buy_fees")).movePointRight(2).longValueExact();proceeds+=new java.math.BigDecimal((String)line.get("disposal_gross")).movePointRight(2).longValueExact();}eq(cost,101L);eq(fee,7L);eq(proceeds,2L*n);generated++;}});
        check("TDS exact observations require separate review and never grant credit",()->{var s=tdsSheet(tdsCsv(tdsRow()),tdsCsv(tdsRow().replace("C1,","S1,")));var r=TaxWorkbench.tds(s);eq(r.get("statement_tds_observation_total"),null);var g=Json.map(Json.list(r.get("groups")).get(0));eq(g.get("status"),"MATCHED_OBSERVATIONS");s.put("decisions",Map.of(g.get("id"),Map.of("status","REVIEWED_OBSERVATIONS")));r=TaxWorkbench.tds(s);eq(r.get("statement_tds_observation_total"),"40000.00");eq(r.get("claim_amount"),null);eq(r.get("tax_credit_eligibility"),"NOT_DETERMINED");});
        check("TDS mismatches missing sides duplicates and unknown never aggregate",()->{for(String right:List.of(tdsCsv(),tdsCsv(tdsRow().replace("40000.00","39999.00")),tdsCsv(tdsRow().replace("40000.00","UNKNOWN")),tdsCsv(tdsRow(),tdsRow().replace("C1,","S2,")))){var r=TaxWorkbench.tds(tdsSheet(tdsCsv(tdsRow()),right));eq(r.get("statement_tds_observation_total"),null);eq(Json.map(Json.list(r.get("groups")).get(0)).get("status"),"REVIEW_REQUIRED");}});
        Clock clock=Clock.fixed(Instant.parse("2026-11-03T20:30:00Z"),ZoneOffset.UTC);Path directory=Files.createTempDirectory("tax-workbench-unit-");
        try(VaultStore store=new VaultStore(directory.resolve("work.vault"),directory.resolve("work.key"))){
            Workspace w=new Workspace(store,clock);String owner=(String)w.register(body("username","work_owner","display_name","Synthetic owner","password","Synthetic-unit-password-19")).get("id"),other=(String)w.register(body("username","work_other","display_name","Other","password","Synthetic-unit-password-20")).get("id"),staff=(String)w.createOperator("work_staff","Sample preparer","Synthetic-unit-password-21","PREPARER").get("id"),admin=(String)w.createOperator("work_admin","Admin","Synthetic-unit-password-22","ADMIN").get("id"),id=(String)w.createCase(owner,body("title","Private workbench","request_id",Workspace.id())).get("id");
            Map<String,Object> first=capitalCommand(w,owner,id);
            check("capital import invalidates reviews and scope; no income auto-transfer",()->{String prior=(String)w.readCase(owner,id).get("snapshot");w.workbenchCommand(owner,id,first);var row=w.readCase(owner,id);eq(prior.equals(row.get("snapshot")),false);eq(Json.map(row.get("profile")).get("screen_special"),"UNKNOWN");eq(Json.map(Json.map(row.get("inputs")).get("SALARY")).get("state"),"UNKNOWN");eq(row.containsKey("tax_workbench"),false);});
            check("capital sale cannot enter narrow assessment even with a false declaration",()->{var row=w.readCase(owner,id);var p=Json.map(row.get("profile"));p.put("screen_special","NO");w.edit(owner,id,body("operation","PROFILE","request_id",Workspace.id(),"expected_revision",row.get("revision"),"profile",p));fail("CAPITAL_GAINS_REQUIRE_EXPANDED_TAX_ENGINE",()->w.calculationSource(owner,id));eq(w.itrReadiness(owner,id).get("status"),"EXPANDED_WORKFLOW_REQUIRED");});
            check("workbench rejects stale version and extra authority fields",()->{var b=command(w,owner,id,"CAPITAL_CLEAR");b.put("workbench_version","old");fail("STALE_TAX_WORKBENCH",()->w.workbenchCommand(owner,id,b));b.put("tax_approved",true);fail("UNEXPECTED_FIELDS",()->w.workbenchCommand(owner,id,b));});
            check("capital review is explicit and old exact request preserves later review",()->{var b=command(w,owner,id,"CAPITAL_REVIEW");b.put("observations_reviewed",false);fail("WORKBENCH_EXPLICIT_REVIEW_REQUIRED",()->w.workbenchCommand(owner,id,b));b.put("observations_reviewed",true);w.workbenchCommand(owner,id,b);String current=Json.encode(w.workbench(owner,id));eq(w.workbenchCommand(owner,id,first).get("status"),"REPLAYED");eq(Json.encode(w.workbench(owner,id)),current);});
            check("sharing grants do not expand private working-paper access",()->{w.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"preparer_username","work_staff","expires_days",7L,"consent",true));eq(w.readCase(staff,id).containsKey("tax_workbench"),false);for(String actor:List.of(staff,admin,other)){fail("CASE_NOT_FOUND",()->w.workbench(actor,id));fail("CASE_NOT_FOUND",()->w.workbenchExport(actor,id));fail("CASE_NOT_FOUND",()->w.workbenchCommand(actor,id,first));}});
            check("clear and replay cannot resurrect records",()->{w.workbenchCommand(owner,id,command(w,owner,id,"CAPITAL_CLEAR"));eq(w.workbenchCommand(owner,id,first).get("status"),"REPLAYED");eq(Json.map(w.workbench(owner,id).get("capital")).get("status"),"NO_CAPITAL_WORKSHEET");});
            check("notice date is user-stated with IST calendar and no legal inference",()->{w.workbenchCommand(owner,id,noticeCommand(w,owner,id));var out=w.workbench(owner,id);eq(out.get("today_ist"),"2026-11-04");var n=Json.map(Json.list(out.get("notices")).get(0));eq(n.get("days_to_user_stated_date"),-1L);eq(n.get("official_submission_verified"),false);eq(n.get("legal_deadline_determined"),false);eq(w.itrReadiness(owner,id).get("status"),"EXPANDED_WORKFLOW_REQUIRED");});
            check("notice response and reported submission require explicit evidence fields",()->{var b=noticeCommand(w,owner,id);b.put("status","RESPONSE_DRAFTED");fail("NOTICE_DRAFT_REQUIRED",()->w.workbenchCommand(owner,id,b));b.put("status","SUBMISSION_REPORTED_UNVERIFIED");fail("NOTICE_USER_REPORTED_RECEIPT_REQUIRED",()->w.workbenchCommand(owner,id,b));b.put("receipt_alias","SYNTHETIC_RECEIPT");b.put("reported_on","2026-11-03");b.put("source_checked",true);w.workbenchCommand(owner,id,b);eq(Json.list(w.workbench(owner,id).get("notices")).size(),2);});
            check("workbench export contains preparation records; audit omits private content",()->{var out=w.exportCase(owner,id);eq(Json.map(out.get("case")).containsKey("tax_workbench"),true);String audit=Json.encode(w.audit(admin));for(String secret:List.of("NOTICE_A","SYNTHETIC_RECEIPT","ACC_A","ASSET_A","40000.00"))eq(audit.contains(secret),false);eq(w.workbenchExport(owner,id).get("tax_approved"),false);});
            check("oversized encrypted case rejects atomically before a receipt",()->{
                String large=(String)w.createCase(owner,body("title","Size guard fixture","request_id",Workspace.id())).get("id");
                store.transaction(state->{var row=Json.map(Workspace.table(state,"cases").get(large));List<Object> notes=new ArrayList<>();for(int i=0;i<50;i++)notes.add(Map.of("id",Workspace.id(),"author","漢".repeat(64),"text","漢".repeat(1000),"input_snapshot",row.get("snapshot"),"at",clock.instant().toString(),"scope","PREPARATION_COMMENT_NOT_CA_SIGNOFF"));row.put("preparation_notes",notes);Workspace.table(state,"cases").put(large,row);return null;});
                List<String> rows=new ArrayList<>();for(int i=1;i<=120;i++)rows.add("BUY_"+i+",ACC_A,ASSET_A,BUY,2024-01-01,"+i+",1,1.00,0.00");var cap=capitalCommand(w,owner,large);cap.put("csv",csv(rows.toArray(String[]::new)));w.workbenchCommand(owner,large,cap);boolean blocked=false;
                for(int i=0;i<8;i++){var b=noticeCommand(w,owner,large);b.put("draft","漢".repeat(3000));String before=Json.encode(w.workbench(owner,large));try{w.workbenchCommand(owner,large,b);}catch(Workspace.Problem e){eq(e.code,"CASE_RECORD_SIZE_LIMIT");eq(Json.encode(w.workbench(owner,large)),before);blocked=true;break;}}eq(blocked,true);
            });
            check("delete denies retained command retry before receipt lookup",()->{var row=w.readCase(owner,id);w.deleteCase(owner,id,body("expected_revision",row.get("revision"),"confirm","DELETE"));fail("CASE_NOT_FOUND",()->w.workbenchCommand(owner,id,first));});
        }finally{try(var paths=Files.walk(directory)){for(Path p:paths.sorted(Comparator.reverseOrder()).toList())Files.deleteIfExists(p);}}
        System.out.println(Json.encode(Map.of("workbench_named_groups",passed,"generated_conservation_cases",generated,"independent_tax_approval",false,"filing_available",false)));
    }
}
